def redact_pdf_comprehensive(input_path, output_path, patterns_dict):
    """
    More comprehensive redaction that handles multi-line text better.
    """
    doc = fitz.open(input_path)

    # Flatten all string patterns
    all_string_patterns = []
    for category, patterns in patterns_dict.items():
        if category == 'symbols':
            continue
        for pattern in patterns:
            if not pattern.startswith('r\'') and '.*' not in pattern and '\\' not in pattern:
                all_string_patterns.append(pattern)

    for page_num, page in enumerate(doc):
        print(f"  Processing page {page_num + 1}/{len(doc)}")
        redaction_count = 0

        # Search for each string pattern
        for pattern in all_string_patterns:
            try:
                text_instances = page.search_for(pattern, quads=True)
                for inst in text_instances:
                    page.add_redact_annot(inst, fill=(0, 0, 0))
                    redaction_count += 1
            except Exception as e:
                print(f"    Warning: Could not search for '{pattern}': {e}")

        # Search for email addresses in page text
        text = page.get_text()
        email_pattern = r'[\w\.\-]+@[\w\.\-]+\.\w+'
        for match in re.finditer(email_pattern, text):
            email = match.group()
            instances = page.search_for(email, quads=True)
            for inst in instances:
                page.add_redact_annot(inst, fill=(0, 0, 0))
                redaction_count += 1

        # Apply all redactions for this page
        page.apply_redactions()

        if redaction_count > 0:
            print(f"    Applied {redaction_count} redactions")

    # Save
    doc.save(output_path, garbage=4, deflate=True)
    doc.close()
    print(f"  Saved to {output_path}")

